import { MotionProps, motion } from "framer-motion";
import styles from "./skeleton-rectangle.module.less";

type Props = {
  width?: number;
  height?: number;
  className?: string;
  style?: React.CSSProperties;
} & MotionProps;

export const SkeletonRectangle = ({ width, height, className, style, ...props }: Props) => {
  const widthAndHeightStyle = {
    width: `${width}rem`,
    height: `${height}rem`,
  };

  return (
    <motion.div
      className={`${styles.skeleton} ${className ? className : ""}`}
      style={{ ...widthAndHeightStyle, ...style }}
      {...props}
    />
  );
};
